// Bina tipi → ikon adı. 'zirh' hem ekipman (zırh) hem bina (zırhçı) olduğu için
// binalar bu köprüden geçmek zorunda: buildingIcon('zirh') === 'zirhci'.
const BUILDING_ALIAS = {
  zirh: 'zirhci',
};
export function buildingIcon(type) {
  return BUILDING_ALIAS[type] || type;
}

// Bina tanımlarındaki tip adı → ikon adı köprüsü
