export default function Icon({ name, size = 18, color = 'currentColor', strokeWidth = 1.6, style, title, className }) {
  if (FILLED[name]) {
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" style={style} className={className}>
        {title && <title>{title}</title>}
        <path d={FILLED[name]} fill={color} fillRule="evenodd" clipRule="evenodd" />
      </svg>
    );
  }
  const key = P[name] ? name : (ALIAS[name] && P[ALIAS[name]] ? ALIAS[name] : null);
  if (!key) {
    // Bilinmeyen tip: nötr altıgen
    return (
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={style} className={className}
        stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
        {title && <title>{title}</title>}
        <path d="M12 3.5 19.5 8v8L12 20.5 4.5 16V8z" opacity="0.55" />
      </svg>
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={style} className={className}
      stroke={color} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round">
      {title && <title>{title}</title>}
      {P[key]}
    </svg>
  );
}

// Ekipman ikonlarını bina ikonundan ayırmak için özel isim
export const EQUIPMENT_ICON = {
  kilic: 'kilic', mizrak: 'mizrak', kalkan: 'kalkan', zirh: 'zirh', at: 'at',
};

export function hasIcon(name) {
  return !!(P[name] || (ALIAS[name] && P[ALIAS[name]]));
}
